from re import search

from taf.rfrl.procedures.resources.python.bts.sw.sw_stream import SwStream


class SwVersionDu:
    """ Represents BTS software version on DU. """

    def __init__(self, name: str):
        """
        :param name: DU software version name, i.e. 'vDUCNF25R3_26.300.354'.
        """
        self._name = name
        self._stream = SwStream(name=search(r'([0-9]{2}R[123])', name).group(1))

    @property
    def name(self) -> str:
        """ Returns DU software version name, i.e. 'vDUCNF25R3_26.300.354'. """
        return self._name

    @property
    def stream(self) -> SwStream:
        """ Returns DU software version stream, i.e. '25R3'. """
        return self._stream
